import{_ as l,a0 as o,w as d,s as r,ao as p,I as e,x as n,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"七個使用 wget 命令的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"七個使用 wget 命令的技巧 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"七個使用 wget 命令的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"七個使用 wget 命令的技巧 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211021 7 handy tricks for using the Linux wget command","title":"七個使用 wget 命令的技巧","tag":"202111","desc":""},"relativePath":"202111/20211021 7 handy tricks for using the Linux wget command.md","filePath":"[post].md"}'),g={name:"202111/20211021 7 handy tricks for using the Linux wget command.md"};function c(h,s,u,b,k,m){const a=o("Link");return d(),r("div",null,[s[35]||(s[35]=p(`<h1 id="七個使用-wget-命令的技巧" tabindex="-1">七個使用 wget 命令的技巧 <a class="header-anchor" href="#七個使用-wget-命令的技巧" aria-label="Permalink to “七個使用 wget 命令的技巧”">​</a></h1><blockquote><p>用你的 Linux 終端中從互聯網上下載文件。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/22/102927pjuji5juxzuikkg6.jpg" alt=""></p><p><code>wget</code> 是一個下載網頁文件的免費工具。它將互聯網上的數據保存到一個文件或展示在終端上。實際上這也是像 Firefox 或 Chromium 這樣的網頁瀏覽器的工作原理。有一個區別是，網頁瀏覽器默認將網頁 <ruby>渲染<rt>render</rt></ruby>在圖形窗口中，並且通常需要用户主動來操作它們。而 <code>wget</code> 工具是無交互的使用方式，也就是説你可以使用腳本或定期使用 <code>wget</code> 來下載文件，不論你人是否在電腦面前。</p><h3 id="使用-wget-下載文件" tabindex="-1">使用 wget 下載文件 <a class="header-anchor" href="#使用-wget-下載文件" aria-label="Permalink to “使用 wget 下載文件”">​</a></h3><p>你可以通過提供一個特定 URL 的鏈接，用 <code>wget</code> 下載一個文件。如果你提供一個默認為 <code>index.html</code> 的 URL，那麼就會下載該索引頁。默認情況下，文件會被下載到你當前的工作目錄，並保持原來的名字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://example.com</span></span>
<span class="line"><span>--2021-09-20 17:23:47-- http://example.com/</span></span>
<span class="line"><span>Resolving example.com... 93.184.216.34, 2606:2800:220:1:248:1893:25c8:1946</span></span>
<span class="line"><span>Connecting to example.com|93.184.216.34|:80... connected.</span></span>
<span class="line"><span>HTTP request sent, awaiting response... 200 OK</span></span>
<span class="line"><span>Length: 1256 (1.2K) [text/html]</span></span>
<span class="line"><span>Saving to: &#39;index.html&#39;</span></span></code></pre></div><p>通過使用 <code>--output-document</code> 和 <code>-</code> 符號，你可以指示 <code>wget</code> 將數據發送到 <ruby>標準輸出<rt>stdout</rt></ruby>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://example.com --output-document - | head -n4</span></span>
<span class="line"><span>&lt;!doctype html&gt;</span></span>
<span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>&lt;head&gt;</span></span>
<span class="line"><span>   &lt;title&gt;Example Domain&lt;/title&gt;</span></span></code></pre></div><p>你可以使用 <code>--output-document</code> 選項（簡寫為 <code>-O</code>）將下載文件命名為任何你想要的名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://example.com --output-document foo.html</span></span></code></pre></div><h3 id="斷點續傳" tabindex="-1">斷點續傳 <a class="header-anchor" href="#斷點續傳" aria-label="Permalink to “斷點續傳”">​</a></h3><p>如果你正在下載一個超大文件，你可能會遇到中斷下載的情況。使用 <code>--continue</code>（簡寫為 <code>-c</code>），<code>wget</code> 可以確定從文件的哪個位置開始繼續下載。也就是説，下次你在下載一個 4 GB 的 Linux 發行版 ISO 時，如果出現了錯誤導致中斷，你不必重新從頭開始。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --continue https://example.com/linux-distro.iso</span></span></code></pre></div><h3 id="下載一系列的文件" tabindex="-1">下載一系列的文件 <a class="header-anchor" href="#下載一系列的文件" aria-label="Permalink to “下載一系列的文件”">​</a></h3><p>如果你要下載的不是單個大文件，而是一系列的文件，<code>wget</code> 也能提供很好的幫助。假如你知道要下載文件的路徑以及文件名的通用範式，你可以使用 Bash 語法指示一個數字範圍的起始和終點來表示這一系列文件名:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://example.com/file_{1..4}.webp</span></span></code></pre></div><h3 id="鏡像整個站點" tabindex="-1">鏡像整個站點 <a class="header-anchor" href="#鏡像整個站點" aria-label="Permalink to “鏡像整個站點”">​</a></h3><p>使用 <code>--mirror</code> 選項你可以下載整個站點，包括它的目錄結構。這與使用選項 <code>--recursive --level inf --timestamping --no-remove-listing</code> 的效果是一樣的，該選項表明可以進行無限制的遞歸，得到你指定域下的所有內容。但你也可能會得到比預期多得多的內容，這取決於站點本身的老舊程度。</p><p>如果你正在使用 <code>wget</code> 來打包整個站點，選項 <code>--no-cookies --page-requisites --convert-links</code> 非常有用，它可以確保打包的站點是全新且完整的，站點副本或多或少是<ruby>自包含的<rt>self-contained</rt></ruby>。</p><h3 id="修改-html-標頭" tabindex="-1">修改 HTML 標頭 <a class="header-anchor" href="#修改-html-標頭" aria-label="Permalink to “修改 HTML 標頭”">​</a></h3><p>在計算機發送的通信報文裏含有大量用於數據交換的<ruby>元數據<rt>metadata</rt></ruby>。HTTP 標頭是初始數據的組成部分。當你瀏覽某個站點時，你的瀏覽器會發送 HTTP 請求標頭。使用 <code>--debug</code> 選項可以查看 <code>wget</code> 為每個請求發送了什麼樣的標頭信息:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --debug example.com</span></span>
<span class="line"><span>---request begin---</span></span>
<span class="line"><span>GET / HTTP/1.1</span></span>
<span class="line"><span>User-Agent: Wget/1.19.5 (linux-gnu)</span></span>
<span class="line"><span>Accept: */*</span></span>
<span class="line"><span>Accept-Encoding: identity</span></span>
<span class="line"><span>Host: example.com</span></span>
<span class="line"><span>Connection: Keep-Alive</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---request end---</span></span></code></pre></div><p>你可以使用 <code>--header</code> 選項修改請求標頭。實際上經常使用這種方式來模仿某特定瀏覽器，來測試或兼容某些編碼糟糕、只能與特定代理通信的站點。</p><p>讓請求被識別為來自 Windows 系統的 Microsoft Edge：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --debug --header=&quot;User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36 Edg/91.0.864.59&quot; http://example.com</span></span></code></pre></div><p>你也可以假裝為某個移動設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --debug --header=&quot;User-Agent: Mozilla/5.0 (iPhone; CPU iPhone OS 13_5_1 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/13.1.1 Mobile/15E148 Safari/604.1&quot; http://example.com</span></span></code></pre></div><h3 id="查看響應標頭" tabindex="-1">查看響應標頭 <a class="header-anchor" href="#查看響應標頭" aria-label="Permalink to “查看響應標頭”">​</a></h3><p>與瀏覽器發送請求標頭的方式一樣，響應也包含有標頭信息。你可以使用 <code>--debug</code> 選項來查看響應中的標頭信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --debug example.com</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>---response begin---</span></span>
<span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>Accept-Ranges: bytes</span></span>
<span class="line"><span>Age: 188102</span></span>
<span class="line"><span>Cache-Control: max-age=604800</span></span>
<span class="line"><span>Content-Type: text/html; charset=UTF-8</span></span>
<span class="line"><span>Etag: &quot;3147526947&quot;</span></span>
<span class="line"><span>Server: ECS (sab/574F)</span></span>
<span class="line"><span>Vary: Accept-Encoding</span></span>
<span class="line"><span>X-Cache: HIT</span></span>
<span class="line"><span>Content-Length: 1256</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---response end---</span></span>
<span class="line"><span>200 OK</span></span>
<span class="line"><span>Registered socket 3 for persistent reuse.</span></span>
<span class="line"><span>URI content encoding = &#39;UTF-8&#39;</span></span>
<span class="line"><span>Length: 1256 (1.2K) [text/html]</span></span>
<span class="line"><span>Saving to: &#39;index.html&#39;</span></span></code></pre></div><h3 id="處理-301-響應" tabindex="-1">處理 301 響應 <a class="header-anchor" href="#處理-301-響應" aria-label="Permalink to “處理 301 響應”">​</a></h3><p>200 響應碼意味着一切都在預料之中。而 301 響應則表示 URL 已經被永久遷移到了另外一個地方。這是站點管理員的一種常用手段，內容遷移後，為訪問舊地址的用户留下尋找新地址的“線索”。<code>wget</code> 會默認跟隨<ruby>重定向<rt>redirect</rt></ruby>，這也是大部分情況下用户所希望的。</p><p>當然，你可以使用 <code>--max-redirect</code> 選項，用於控制 <code>wget</code> 默認處理 301 響應重定向的次數。設置為 <code>0</code> 意味着不會自動重定向到新的地址:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --max-redirect 0 http://iana.org</span></span>
<span class="line"><span>--2021-09-21 11:01:35-- http://iana.org/</span></span>
<span class="line"><span>Resolving iana.org... 192.0.43.8, 2001:500:88:200::8</span></span>
<span class="line"><span>Connecting to iana.org|192.0.43.8|:80... connected.</span></span>
<span class="line"><span>HTTP request sent, awaiting response... 301 Moved Permanently</span></span>
<span class="line"><span>Location: https://www.iana.org/ [following]</span></span>
<span class="line"><span>0 redirections exceeded.</span></span></code></pre></div><p>同時，你也可以設置為其他的數值來控制 <code>wget</code> 能重定向多少次。</p><h3 id="展開-url-縮寫" tabindex="-1">展開 URL 縮寫 <a class="header-anchor" href="#展開-url-縮寫" aria-label="Permalink to “展開 URL 縮寫”">​</a></h3>`,37)),e("p",null,[s[1]||(s[1]=n("使用",-1)),s[2]||(s[2]=e("code",null,"--max-redirect",-1)),s[3]||(s[3]=n(" 選項用於在實際訪問之前查看 ",-1)),s[4]||(s[4]=e("ruby",null,[n("URL 縮寫"),e("rt",null,"shortened URL")],-1)),s[5]||(s[5]=n("非常有用。縮寫 URL 可用於用户無法完整拷貝和粘貼一個長 URL 時的",-1)),s[6]||(s[6]=e("ruby",null,[n("印刷媒體"),e("rt",null,"print media")],-1)),s[7]||(s[7]=n("，或是具有字數限制的社交網絡（在類似 ",-1)),t(a,{href:"https://opensource.com/article/17/4/guide-to-mastodon"},{default:i(()=>[...s[0]||(s[0]=[n("Mastondon",-1)])]),_:1}),s[8]||(s[8]=n(" 這種現代開源的社交網絡上這並不是一個問題）。這種縮寫具有一定的風險，因為本質上這些目的地是隱藏的。組合使用 ",-1)),s[9]||(s[9]=e("code",null,"--head",-1)),s[10]||(s[10]=n(" 選項和 ",-1)),s[11]||(s[11]=e("code",null,"--location",-1)),s[12]||(s[12]=n(" 選項來來查看 HTTP 頭部並解開最終的目的地，你可以在不加載整個資源的情況下查看到縮寫 URL 的完整內容：",-1))]),s[36]||(s[36]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --max-redirect 0 &quot;https://bit.ly/2yDyS4T&quot;</span></span>
<span class="line"><span>--2021-09-21 11:32:04-- https://bit.ly/2yDyS4T</span></span>
<span class="line"><span>Resolving bit.ly... 67.199.248.10, 67.199.248.11</span></span>
<span class="line"><span>Connecting to bit.ly|67.199.248.10|:443... connected.</span></span>
<span class="line"><span>HTTP request sent, awaiting response... 301 Moved Permanently</span></span>
<span class="line"><span>Location: http://example.com/ [following]</span></span>
<span class="line"><span>0 redirections exceeded.</span></span></code></pre></div><p>從 <code>Location</code> 開始的倒數第二行輸出，展示了實際的目的地。</p><h3 id="使用-wget" tabindex="-1">使用 wget <a class="header-anchor" href="#使用-wget" aria-label="Permalink to “使用 wget”">​</a></h3>`,3)),e("p",null,[s[14]||(s[14]=n("若你開始考慮使用單個命令來實現整個網站訪問的過程，",-1)),s[15]||(s[15]=e("code",null,"wget",-1)),s[16]||(s[16]=n(" 可以快速高效的幫你獲取互聯網上的信息，而不用在圖形界面上耗費精力。為了幫你將它構造在你平常的工作流中，我們創建了一個 ",-1)),s[17]||(s[17]=e("code",null,"wget",-1)),s[18]||(s[18]=n(" 常用使用方式和語法清單，包括使用它來查詢 API 的概述。",-1)),t(a,{href:"https://opensource.com/downloads/linux-wget-cheat-sheet"},{default:i(()=>[...s[13]||(s[13]=[n("在這裏下載 Linux wget 速查表",-1)])]),_:1}),s[19]||(s[19]=n("。",-1))]),s[37]||(s[37]=e("hr",null,null,-1)),e("p",null,[s[21]||(s[21]=n("來源: ",-1)),t(a,{href:"https://opensource.com/article/21/10/linux-wget-command"},{default:i(()=>[...s[20]||(s[20]=[n("https://opensource.com/article/21/10/linux-wget-command",-1)])]),_:1})]),e("p",null,[s[26]||(s[26]=n("作者：",-1)),t(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[22]||(s[22]=[n("Seth Kenlon",-1)])]),_:1}),s[27]||(s[27]=n(" 選題：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[23]||(s[23]=[n("lujun9972",-1)])]),_:1}),s[28]||(s[28]=n(" 譯者：",-1)),t(a,{href:"https://github.com/zengyi1001"},{default:i(()=>[...s[24]||(s[24]=[n("zengyi1001",-1)])]),_:1}),s[29]||(s[29]=n(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[25]||(s[25]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[32]||(s[32]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[30]||(s[30]=[n("LCTT",-1)])]),_:1}),s[33]||(s[33]=n(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...s[31]||(s[31]=[n("Linux中國",-1)])]),_:1}),s[34]||(s[34]=n(" 榮譽推出",-1))])])}const w=l(g,[["render",c]]);export{y as __pageData,w as default};
